def add(a, b):
    """Return the sum of two numbers."""
    return a + b

def factorial(n):
    """Return n! for non-negative integers."""
    if n < 0:
        raise ValueError('n must be >= 0')
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def fizzbuzz(n):
    """Return list of FizzBuzz strings for 1..n."""
    out = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            out.append('FizzBuzz')
        elif i % 3 == 0:
            out.append('Fizz')
        elif i % 5 == 0:
            out.append('Buzz')
        else:
            out.append(str(i))
    return out

def reverse_string(s):
    """Return s reversed."""
    return s[::-1]

def max_of_list(lst):
    """Return the maximum value in lst, raising ValueError if empty."""
    if not lst:
        raise ValueError('empty list')
    m = lst[0]
    for x in lst[1:]:
        if x > m:
            m = x
    return m

def count_vowels(s):
    """Return number of vowels in s (case-insensitive)."""
    return sum(1 for c in s.lower() if c in 'aeiou')

def fib(n):
    """Return the n-th Fibonacci number (fib(0)=0, fib(1)=1)."""
    if n < 0:
        raise ValueError('n must be >= 0')
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def get_initials(name):
    """Return uppercase initials of a space-separated name."""
    return ''.join(part[0].upper() for part in name.split() if part)

def clamp(x, lo, hi):
    """Clamp x into the inclusive range [lo, hi]."""
    if lo > hi:
        raise ValueError('lo must be <= hi')
    return max(lo, min(hi, x))
